#!/usr/bin/env python3
"""Render a standalone offline interaction prototype; scenario data is display-only."""
import json
from pathlib import Path
HERE=Path(__file__).resolve().parent
scenarios=json.loads((HERE/'scenarios.json').read_text())
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>veri7vn · workspace interaction study</title><link rel="icon" href="data:,">
<style>
:root{font-family:system-ui,sans-serif;color:#20312e;background:#edece6;line-height:1.5}*{box-sizing:border-box}body{margin:0}button,a{font:inherit}button{cursor:pointer;border:1px solid #a0aaa1;border-radius:5px;padding:9px 14px;background:#fafaf5;color:#20312e}button:hover,button:focus-visible{background:#d9e9dc;outline:2px solid #315c47}button.primary{background:#245640;color:white}header{padding:16px 28px;background:#163e30;color:#fff;display:flex;justify-content:space-between;gap:20px}header strong{font-size:21px}.study{padding:9px 28px;background:#e8d9b6;font-size:13px}.layout{display:grid;grid-template-columns:240px 1fr;min-height:80vh}nav{padding:23px 15px;border-right:1px solid #c6cbc1}nav button{display:block;text-align:left;width:100%;margin:5px 0;background:transparent;border:0;font-size:13px}nav button[aria-current=true]{background:#d6e3d7;font-weight:700}main{padding:30px;max-width:1250px;width:100%}.top{display:flex;justify-content:space-between;align-items:start;gap:16px}.muted{color:#5c6a63;font-size:13px}h1{font-family:Georgia,serif;font-size:34px;line-height:1.15;font-weight:500;margin:10px 0 16px}h2{font-size:16px;margin:0 0 10px}.summary{max-width:780px;margin:0 0 20px}.axes{display:flex;flex-wrap:wrap;gap:7px;margin:22px 0}.axes span{padding:7px 10px;border:1px solid #abb9ad;border-radius:20px;background:#f5f7ef;font-size:12px}.columns{display:grid;grid-template-columns:1.6fr 1fr;gap:18px}.card{padding:22px;background:#fbfcf7;border:1px solid #d1d5ca;border-radius:8px}.notice{border-left:4px solid #b8882b;background:#f6eedb;padding:16px 18px;margin-bottom:20px}dl{margin:0}dt{font-weight:650;margin-top:18px;font-size:14px}dt:first-child{margin-top:0}dd{margin:4px 0 0;white-space:pre-wrap}.actions{display:flex;gap:9px;flex-wrap:wrap;margin:22px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#17382f;color:#eaf4dc;padding:15px;border-radius:6px;font-size:12px}aside p{font-size:14px}details{margin-top:20px}footer{margin-top:22px;display:flex;justify-content:space-between;gap:15px}.toast{padding:14px;background:#d7e9dc;border:1px solid #86a18b;border-radius:5px;margin:12px 0}.sr{position:absolute;width:1px;height:1px;overflow:hidden}a{color:#25583e}@media(max-width:900px){.columns{grid-template-columns:1fr}.layout{grid-template-columns:1fr}nav{display:flex;overflow:auto;padding:8px}nav button{min-width:190px}main{padding:20px}header{padding:14px}.top{display:block}}
</style>
<header><strong>veri7vn <small style="font-weight:400">/ workshop</small></strong><span>Local workspace · development and deployed use</span></header>
<div class="study">Design preview · illustrative examples; actions do not run</div>
<div class="layout"><nav aria-label="Author walkthroughs" id="nav"></nav><main id="main" tabindex="-1"></main></div>
<script>const scenarios=__DATA__;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function show(id,focus=false){const s=scenarios.find(x=>x.id===id)||scenarios[0];location.hash=s.id;
document.querySelector('#nav').innerHTML=scenarios.map(x=>`<button data-id="${x.id}" aria-current="${x.id===s.id}">${esc(x.title)}</button>`).join('');
document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>show(b.dataset.id,true));
document.querySelector('#main').innerHTML=`<div class="top"><div><div class="muted">${esc(s.package)}</div><h1>${esc(s.title)}</h1></div><button id="next">Next walkthrough →</button></div><p class="summary">${esc(s.summary)}</p><div class="axes" aria-label="Independent readiness states">${s.axis.map(a=>`<span>${esc(a)}</span>`).join('')}</div><div class="notice">${esc(s.notice)}</div><div class="columns"><section class="card"><h2>${esc(s.question)}</h2><dl>${s.rows.map(r=>`<dt>${esc(r[0])}</dt><dd>${esc(r[1])}</dd>`).join('')}</dl><div class="actions">${s.actions.map((a,i)=>`<button class="${i===0?'primary':''}" data-action="${i}">${esc(a)}</button>`).join('')}</div><div id="action-result" role="status"></div></section><aside class="card"><h2>Inspect this version</h2><p>${esc(s.source)}</p><p>Review the original question, source and previous results.</p><details><summary>Advanced: checks and terminal command</summary><p>${s.precise_axis.map(esc).join("<br>")}</p><pre>${esc(s.cli)}</pre><p class="muted">Proposed command; this design preview is not connected to the runtime.</p></details><details><summary>Keyboard and recovery</summary><p>Tab reaches every control. Enter activates a focused action. Alt + → advances the walkthrough. A conflict opens the source comparison; it never overwrites a newer revision. Reconnect reads operation status before retrying.</p></details><details><summary>Audit origin</summary><p>${esc(s.origin)}</p><p>Scenario JSON is an illustrative view fixture, not another editable semantic package.</p></details></aside></div><footer class="muted"><span>Your source edits, check results and active versions stay in history.</span><span>${esc(s.id)} · ${scenarios.findIndex(x=>x.id===s.id)+1}/${scenarios.length}</span></footer>`;
document.querySelector('#next').onclick=()=>show(s.next,true);
document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{document.querySelector('#action-result').className='toast';document.querySelector('#action-result').textContent=`Design preview — ${s.previews[+b.dataset.action]} This prototype executes no operation.`});
if(focus)document.querySelector('#main').focus();}
window.addEventListener('hashchange',()=>show(location.hash.slice(1)));
window.addEventListener('keydown',e=>{if(e.altKey&&e.key==='ArrowRight'){e.preventDefault();document.querySelector('#next').click()}});show(location.hash.slice(1));
</script></html>'''
(HERE/'index.html').write_text(page.replace('__DATA__',json.dumps(scenarios).replace('</','<\\/')))
print(f'Rendered {len(scenarios)} walkthroughs')
